import { writeFile } from "node:fs/promises";
import { join } from "node:path";

const args = process.argv.slice(2);

if (args.includes("--version")) {
  process.stdout.write("codex-cli 0.153.0\n");
  process.exit(0);
}

if (!args.includes("exec")) {
  process.stderr.write("expected exec\n");
  process.exit(2);
}

const mode = process.env.SKILLBENCH_FAKE_CODEX_MODE ?? "success";

if (mode === "timeout") {
  setInterval(() => undefined, 1_000);
  await new Promise(() => undefined);
}

if (mode === "signal") {
  process.kill(process.pid, "SIGTERM");
  await new Promise((resolve) => setTimeout(resolve, 100));
}

if (mode === "nonzero") {
  process.stdout.write(`${JSON.stringify({ type: "turn.failed", error: { message: "fake failure" } })}\n`);
  process.stderr.write("fake codex failure\n");
  process.exit(7);
}

if (mode === "incompatible") {
  process.stdout.write("not-json\n");
  process.exit(0);
}

await writeFile(join(process.cwd(), "generated.txt"), "generated by fake Codex\n");
await writeFile(join(process.cwd(), "argv.json"), `${JSON.stringify(args)}\n`);

for (const event of [
  { type: "thread.started", thread_id: "fake-thread" },
  { type: "turn.started" },
  {
    type: "item.completed",
    item: { id: "item-1", type: "agent_message", text: "FAKE_CODEX_OK" },
  },
  {
    type: "turn.completed",
    usage: {
      input_tokens: 13,
      cached_input_tokens: 3,
      output_tokens: 5,
      reasoning_output_tokens: 2,
    },
  },
]) {
  process.stdout.write(`${JSON.stringify(event)}\n`);
}

if (mode === "large") process.stderr.write("x".repeat(16_384));
